const data = $input.first().json.data;

// Filtrer les messages valides (non null et non vides)
const validMessages = data.filter(item => 
    item.message && 
    item.message.trim() !== '' && 
    item.message !== null
);

// Grouper par id_session
const sessions = {};
validMessages.forEach(item => {
    const sessionId = item.id_session;

    if (!sessions[sessionId]) {
        sessions[sessionId] = {
            channel: item.channel,
            phone_number: item.phone_number,
            messages: []
        };
    }

    sessions[sessionId].messages.push({
        id: item.id,
        sender: item.sender,
        message: item.message
    });
});

// Créer le prompt pour ChatGPT
let prompt = `Analyse des conversations prospects - ${new Date().toISOString().split('T')[0]}\n\n`;

prompt += "Voici les conversations récentes avec des prospects :\n\n";

Object.entries(sessions).forEach(([sessionId, session], index) => {
    prompt += `=== CONVERSATION ${index + 1} ===\n`;
    prompt += `Session ID: ${sessionId}\n`;
    prompt += `Canal: ${session.channel}\n`;
    prompt += `Téléphone: ${session.phone_number || 'Non spécifié'}\n\n`;

    prompt += "Messages:\n";
    session.messages.forEach(msg => {
        prompt += `${msg.sender}: "${msg.message}"\n`;
    });
    prompt += "\n";
});

prompt += `
INSTRUCTIONS D'ANALYSE :

Analyse ces conversations et fournis une synthèse structurée avec :

1. **Résumé exécutif** : Vue d'ensemble des interactions
2. **Profil des prospects** : Types de clients contactant
3. **Besoins identifiés** : Services recherchés
4. **Qualité des leads** : Niveau d'engagement (chaud/tiède/froid)
5. **Opportunités commerciales** : Prospects à prioriser
6. **Actions recommandées** : Prochaines étapes
7. **Améliorations suggérées** : Optimisation du processus

Sois concret et actionnable dans tes recommandations.
`;

// Statistiques
const totalMessages = validMessages.length;
const totalSessions = Object.keys(sessions).length;
const channelStats = {};
validMessages.forEach(item => {
    channelStats[item.channel] = (channelStats[item.channel] || 0) + 1;
});

return [{
    json: {
        prompt: prompt,
        statistics: {
            total_messages: totalMessages,
            total_sessions: totalSessions,
            channels: channelStats,
            generated_at: "2025-10-24 12:45:02",
            generated_by: "neyous"
        }
    }
}];

